BCE={1:"独一的神：纯粹的灵、永恒、不可测透、全能、公义、良善。",2:"认识神的两条路：创造（使人无可推诿）与圣言（更清楚完全）。",3:"圣经不出于人意，乃是圣灵感动；神吩咐记录成文。",4:"旧约与新约同为正典，绝对无误；列出各书卷。",5:"正典的权威来自圣灵在心中的见证，而非教会的认可。",6:"次经可读，但无正典的权威。",7:"圣经包含神全部旨意，充分教导救恩与敬拜；人的著作不可与之等同。",8:"一个本质，三个位格；永远截然不同，却是同一位神。",9:"三位一体的根据是圣经的见证（旧约隐约，新约清晰）。",10:"基督是神的独生子，永恒受生，非受造，与父同本质。",11:"圣灵从永恒中由父与子而出，同本质，是永活的真神。",12:"父藉着子创造万物；天使有的堕落，有的蒙保守；魔鬼是教会的仇敌。",13:"神的护理：没有他的旨意或许可，什么也不会发生；神不是罪的创造者。护理带来安慰。",14:"人被造有神的形象；堕落后全面败坏，只剩些许痕迹；弃绝自由意志的教导。",15:"原罪遍及全人类，使人性全然败坏；神不将它归给他的儿女；弃绝伯拉纠派。",16:"拣选：神的恩慈与公义，在亚当后裔的堕落中显明。",17:"神寻找堕落的人，以“要伤蛇的头”的应许安慰人。",18:"神成就应许：差遣独生子取了真正的人性（身体与灵魂），只是没有罪。",19:"一个位格，神人二性；不存在两位神子。",20:"神的公义与怜悯在基督身上同时彰显。",21:"基督是永远的大祭司，代替我们献上自己，平息神的忿怒。",22:"圣灵在心中生发真信心；信靠基督是完全的救恩（基督不是“半个救主”）。",23:"罪得赦免，在神面前得称为义；不靠行为，不夸自己。",24:"真信心使人重生，不可能不结出善行的果子。",25:"礼仪律已被成全；仍用律法与先知的见证坚固信仰、安排生活。",26:"基督是唯一的中保与代求者，不另寻中保。",27:"圣而公之教会：从世界起初到末了，基督不可能没有臣民。",28:"所有信徒都有责任加入并维护教会，不应孤立生活。",29:"真教会的三标志：纯正福音、按设立施行圣礼、执行纪律。",30:"教会由牧师、长老、执事治理。",31:"牧师、长老、执事经合法选举与神的呼召。",32:"规章不得束缚良心；纪律须符合神的话语。",33:"圣礼是内在不可见之事的外在标记与印证，辅助圣言。",34:"洗礼取代割礼；信徒的婴孩也当受洗；拒绝重洗。",35:"圣餐：基督在天，圣灵使我们凭信心与他相交，属灵地吃喝。",36:"官长的设立与职分；信徒的顺服；谴责造反的重洗派。",37:"基督再来审判：对恶人可怕，对蒙选者是极大的喜乐与安慰。"}
GROUPS=[("神","#5aa9e6",[1,8,9,10,11]),("圣经","#a78bfa",[2,3,4,5,6,7]),("创造与人","#81b29a",[12,13,14,15]),("基督与拣选","#d4af37",[16,17,18,19,20,21]),("救恩的应用","#e0a85f",[22,23,24,25,26]),("教会与圣礼","#e07a5f",[27,28,29,30,31,32,33,34,35]),("政府与末日","#6bb8d6",[36,37])]
def bcmap():
    gof={n:(g,c) for g,c,ns in GROUPS for n in ns}
    out='<div class="bcm reveal" role="group" aria-label="比利时信条37条地图"><div class="bcl">'+"".join(f'<span style="--c:{c}"><i></i>{g}</span>' for g,c,_ in GROUPS)+'</div><div class="bct">'
    for n in range(1,38):
        g,c=gof[n]; t=BCT[n]
        out+=f'<a class="bt" href="#bc-{n}" style="--c:{c};--i:{n}" title="第{n}条 {t}：{BCE[n]}"><b>{n}</b><small>{t[:8]}</small></a>'
    return out+'</div><p class="bcn">点任一方块跳到原文（本站已把 CCI 的 37 条按内容着色分群，这是本站的分组）。</p></div>'

def _first(ref,txt):
    t=txt.split("。")[0]
    if len(t)>84:
        k=t.find("，",34); t=t[:k] if k>0 else t[:84]
    elif txt.find("。")>=0: t=t+"。"
    return t
def bc37_l2():
    from libs import rdet,bc_rows
    from c_titles import BC37,BC_GROUPS
    from quotes import BC
    from c_core import BC_CORE,core_strip
    x=('<p>37 条按七群分，每条一个三级标题（编号 3.2.1–3.2.37）：<b>短标题</b>（本站学习标题）、<b>口诀</b>、<b>CCI 首句</b>（逐字摘引）与原文链接；CCI 的正式条目标题见第八部分。颜色＝所属群。</p>'
       +'<nav class="bcn" aria-label="七群">'+"".join(f'<a href="#bcg-{g}" style="border-color:{c}">{lab} {lo}–{hi}</a>' for g,lab,c,lo,hi,_ in BC_GROUPS)+'</nav>')
    for g,lab,col,lo,hi,ico in BC_GROUPS:
        x+=f'<h4 class="qh pdv" id="bcg-{g}" style="border-left:4px solid {col}">{lab}<small>第{lo}–{hi}条</small></h4>'
        for n in range(lo,hi+1):
            t,kw,ic_=BC37[n]; q=_first("BC "+str(n),BC[n])
            body=(f'<div class="l3m"><span class="pch p2" style="background:{col}">{lab}</span><span class="qr">{BCT[n]}</span><span class="kw">{"".join(f"<i>{w}</i>" for w in kw.replace("＋","·").split("·"))}</span></div>'
                  +core_strip(BC_CORE[n])+f'<p><i class="lb">CCI 首句</i>{Q("BC "+str(n),q)}</p>'+rdet(f"第{n}条",bc_rows(n),sum(len(x) for _,x in bc_rows(n)))+f'<p class="lk"><a href="bct.html#bc-{n}">读第{n}条全文（CCI 原文）</a> · <a href="memory.html#mem-bc">记忆页：标题速记</a></p>')
            x+=L3(f"bcd-a{n}",f"第{n}条 · {t}",body,ic_,sub=f"BC {n}",cls="ldc")
    return L2("bcd-37","3.2","37 条主题标题目录：短标题、口诀与首句",x)

def part_bc():
    b = pagecore("一份在逼迫中写给国王与教会的告白：神—人—基督—救恩—教会—末事，三十七条。","七群：神与启示｜创造与人｜基督与拣选｜救恩应用｜教会｜圣礼｜官长与末日","第34条婴孩洗礼的“圣约”论证；第36条官长一节的历史修订（CCI 注明1905年删去一句）。")+whole_bc()+L2("bcd-map","3.1","结构：37 条的地图",
      '<p>比利时信条（BC，又名《真基督教信条》）按教义条目写成，从“只有一位神”开始，到“主耶稣啊，我愿你来”结束。CCI 的原文库按条目逐条列出；本页把它们<b>按内容分成七群</b>并画成地图（本站分组，不是 CCI 的目录）：</p>'
      + bcmap()
      + flow([("神与启示","1–11","#5aa9e6"),("创造与人","12–15","#81b29a"),("基督与拣选","16–21","#d4af37"),("救恩的应用","22–26","#e0a85f"),("教会与圣礼","27–35","#e07a5f"),("政府与末日","36–37","#6bb8d6")])
      + key("<b>读法：</b>BC 的顺序是“神—人—基督—救恩—教会—末事”。它不是照 HC 的“愁苦—得救—感恩”写，而是一份完整的<b>教义告白</b>：每一条都以“我们相信”开头（CCI 的原文如此）。")
      + note("CCI 的 BC 导言说，BC 被称为《真基督教信条》，其标题 CCI 写作“对有关神的教义和有关人得永恒救赎的教义的概述”。"))
    # 3.2 故事
    st=story([("尼德兰南部的传道人","德布利（Guido de Brès）是荷兰改革宗教会的牧师（CCI）。他在当时的荷兰南部（今比利时一带）传道；一般认为他生于蒙斯（约），曾在日内瓦受教（约）。"),
              ("1561：为何写","CCI：当时荷兰的教会受到罗马天主教政府极为残酷的逼迫；德布利为了抗议这种逼迫，也为了向逼迫者表明改革宗信徒不是被指控的“叛乱者”，而是“照着圣经宣告真基督教信仰的守法公民”，于1561年写下信条。"),
              ("借鉴法国信条","CCI：写作在一定程度上得益于加尔文主笔、比 BC 早两年发表的法国改革宗教会信条；但 BC 不是它的修正版，有自己的特点。"),
              ("呈送国王","CCI：第二年（1562）一份抄本连同信徒请愿书送到腓利二世手中：愿在一切合法的事上顺服政府；若要否认信条，宁愿“背受鞭笞，舌被刀割，身受火刑”。相传还有把抄本抛过图尔奈城堡围墙的故事（相传，约，史料有争议）。"),
              ("殉道","CCI：初衷（使信徒免受逼迫）没有实现，德布利于1567年为主殉道，成为成千上万名殉道者之一；一般记为在瓦朗谢讷被处死（约）。"),
              ("信条存留","CCI：信条得到荷兰许多教会欢迎；16世纪最后三十年间的几次总会审议并正式采纳；1618–1619年多特大会经仔细修订（主要在文字）正式纳为三项联合信条之一。")])
    b += bc37_l2()
    import storymap as SM
    b += L2("bcd-story","3.2","故事线与思维导图：一份信条与一个殉道者",SM.block("bc"))
    # 3.3 时间线
    tl=[("1522","德布利出生（约）","一般记为生于蒙斯（Mons）；此处年份与地点约。","#a78bfa"),
        ("1559","法国改革宗信条","加尔文主笔，比 BC 早两年发表（CCI）。","#d4af37"),
        ("1561","BC 写成","因残酷逼迫而写；表明信徒不是叛乱者（CCI）。","#5aa9e6"),
        ("1562","呈送腓利二世","抄本与请愿书；宁愿受苦也不否认信条（CCI）。","#5aa9e6"),
        ("1566","圣像破坏运动（约）","尼德兰境内的圣像破坏事件，使政府对改革宗的疑忌加深（本站史背景，约）。","#e07a5f"),
        ("1567","德布利殉道","CCI：为主殉道。","#e07a5f"),
        ("1568","韦瑟尔会晤","荷兰改革宗领袖在逼迫最黑暗的日子会晤，商讨建立教会联盟（CCI 教会规章导言）。","#a78bfa"),
        ("1571","埃姆登第一届总会","CCI 译作“伊顿”（Emden）；许多受逼迫的改革宗信徒避难之地。","#a78bfa"),
        ("约1570–1600","总会审议与采纳","CCI：16世纪最后三十年间的几次总会大会审议并正式采纳 BC。","#d4af37"),
        ("1618–19","多特大会修订并纳入","经仔细修订（主要在文字）正式纳为三大联合信条之一（CCI）。","#81b29a"),
        ("1905","荷兰总会删去一段","CCI 在第36条注明：下文已于1905年被删除——“一切偶像崇拜和虚假敬拜要被除去，敌基督的国要被消灭”。","#6bb8d6")]
