    # 3.4 地图
    pts=["图尔奈（杜内克）","瓦朗谢讷","里尔","蒙斯","布鲁塞尔","根特","安特卫普","米德尔堡","阿姆斯特丹","莱顿","多德雷赫特","韦瑟尔","埃姆登","日内瓦"]
    m=mapsvg("bc","图尔奈（杜内克）与低地国家：BC 的土地",pts,routes=[("日内瓦","图尔奈（杜内克）"),("图尔奈（杜内克）","埃姆登"),("安特卫普","米德尔堡")],hl=("图尔奈（杜内克）","瓦朗谢讷"),bbox=(2,9.5,46,54),
       off={"图尔奈（杜内克）":(14,-10,'start'),"瓦朗谢讷":(-14,10,'end'),"里尔":(-14,-8,'end'),"蒙斯":(14,16,'start'),"布鲁塞尔":(14,-10,'start'),"根特":(-14,-8,'end'),"安特卫普":(14,-6,'start'),"米德尔堡":(-14,-6,'end'),"阿姆斯特丹":(14,-8,'start'),"莱顿":(-14,-8,'end'),"多德雷赫特":(14,18,'start'),"韦瑟尔":(14,12,'start'),"埃姆登":(14,-8,'start'),"日内瓦":(14,-8,'start')},
       blobs=[("南部：法语区与佛兰德",3.7,50.55,1.3,0.7,"#d4af37"),("荷兰、泽兰",4.7,52.0,1.1,0.8,"#5aa9e6")],
       cap="；图尔奈即荷语 Doornik；日内瓦已超出本图北界，仅示意为影响来源（图下方）。")
    traits=cards([("🧵","南部：说法语与佛兰德语的商业城市","图尔奈、里尔、瓦朗谢讷、蒙斯一带靠毛纺、贸易与印刷（本站概括，约）；也是 BC 诞生与逼迫最重的地带（CCI：“源于当时的荷兰南部”）。","#d4af37"),
                  ("👑","哈布斯堡统治","腓利二世的天主教政府；CCI 说“罗马天主教政府极为残酷的逼迫”；对异端的惩罚包括酷刑与火刑（BC 的请愿语：“背受鞭笞，舌被刀割，身受火刑”）。","#e07a5f"),
                  ("🚢","流亡与重组","许多信徒逃往埃姆登等地；总会的组织在流亡与逼迫中成形（CCI 教会规章导言：韦瑟尔1568、埃姆登1571）。","#5aa9e6"),
                  ("📜","南北后来的分野","南部逼迫沉重、改革宗教会受创，北部荷兰省与泽兰后来成为改革宗的稳固区域（本站概括，约）。","#81b29a")],"g4")
    b += L2("bcd-geo","3.4","地理与区域特点：图尔奈与低地国家",'<p>BC 是“<b>一份从十字架下写出的信条</b>”。地图上把图尔奈（杜内克）、瓦朗谢讷放在南部，把埃姆登放在东北——这就是 BC 的“出生地”与“流亡地”。</p>'+m+traits
       + note("CCI 把 Emden 译作“伊顿”、Wesel 译作“威塞尔”；本站地图用现行译名“埃姆登”“韦瑟尔”。图尔奈在 CCI 的 BC 导言中并未出现，此处依一般史料（德布利在图尔奈一带事奉，约）。"))
    # 3.5 逼迫背景
    b += L2("bcd-why","3.5","1561 的信与逼迫：成因与果效",
      table(["成因","BC 里的回应","果效"],[
        ["罗马天主教政府极为残酷的逼迫（CCI）","公开宣告“我们相信”，列出全部信仰；以“真基督教信条”为题","向国王呈送（1562）；信条保存下来，成为流亡教会的纽带"],
        ["被指控为“叛乱者”（CCI）","第36条："+Q("BC 36","在不违反圣经的一切事上顺服他们")+"，并为官长代祷","把“顺服官长”与“良心的自由”同时写入告白；同时谴责造反的重洗派"],
        ["各地教会缺乏统一的教义文本","37 条；明确圣经为唯一准则（BC 3–7）","16世纪各总会审议并采纳；多特大会纳入三大联合信条"],
        ["与罗马教会的分野","BC 7、26、29、32、35（敬拜、中保、真教会、规章、圣餐）","把改革宗与罗马教会的分野，放在“圣经的充分性”的基础上"],
        ["与激进改革者（重洗派）的分野","BC 34（婴孩洗礼）、BC 36（造反）","改革宗站在“圣约、婴孩洗礼、顺服官长”的中间路线"]],"cmp")
      + key("<b>一句话：</b>BC 是一份“<b>既向国王陈情，也向教会宣告</b>”的文件——这使它的语气既清晰又克制，每一条都有“我们相信”的告白，也有“我们弃绝”的界限（如 BC 15、34）。")
      + hard("<b>BC 36 的复杂历史：</b>CCI 的原文在第36条末注明，原来一句关于“偶像崇拜和虚假敬拜要被除去，敌基督的国要被消灭”的话，已于1905年荷兰改革宗教会总会被删除。这提醒读者：<b>政府与教会关系的表述，在后来教会中是有修订的。</b>本站原文库保留 CCI 原样。"))
    # 3.6 逐组深读
    dv=deep([
      ("第 1 条：独一的神","#5aa9e6",[("成因与处境","告白从“我们都心里相信、口里承认只有一位神”开始：这是对各种偶像与迷信的回应；“心里相信、口里承认”呼应罗10:10（CCI 脚注）。"),("说什么","神的属性：纯粹的灵、永恒、不可测透、不可见、不改变、无限、全能、全智、公义、良善、一切美善的泉源（"+bl(1)+"）。"),("联系","HC 25–26；三大信经首句；Dort 1.1。"),("难点","属性的列举有“神的不可测透”与“神是可认识的”的张力——下一条说明“认识”的途径。"),("应用","整个信仰的起点是“神是谁”，而不是“我需要什么”。")]),
      ("第 2–7 条：启示与圣经","#a78bfa",[("成因与处境","宗教改革的核心争论之一：权威在哪里？"+bl(7)+"明确：圣经是充分的，人的传统不能与之等同。"),("说什么","两条路认识神：创造与圣言（"+bl(2)+"）；圣经出于圣灵（"+bl(3)+"）；正典（"+bl(4)+"）；权威来自圣灵在心中的见证而非教会的认可（"+bl(5)+"）；次经可读不可立教义（"+bl(6)+"）；圣经充分（"+bl(7)+"）。"),("关键句",Q("BC 5","与其说这是因为教会接受并赞同它们，倒不如说这是因为圣灵在我们心中作见证")+"；"+Q("BC 7","任何人教导有悖于圣经的道理都是不合法的")+"。"),("联系","HC 21、22；CCI《赐自天上的礼物》第1–6课（讲圣经）；WCF 1。"),("应用","读经、听道时，分辨“圣经说”与“人说”；传统有价值，但不与圣经同权。")]),
      ("第 8–11 条：三位一体","#5aa9e6",[("成因与处境","古代教会的三一教义，是 BC 站在大公信仰之内的标志；BC 9 引用旧约、福音书与使徒书信。"),("说什么","一个本质，三个位格（"+bl(8)+"）；见证（"+bl(9)+"）；基督是永恒受生的真神（"+bl(10)+"）；圣灵从父与子而出（"+bl(11)+"）。"),("关键句",Q("BC 8","他只有一个本质，而有三个位格")+"；"+Q("BC 10","非受造亦非被造")+"；"+Q("BC 11","圣灵从永恒中由父与子而出")+"。"),("联系","尼西亚信经；亚他那修信经；HC 24–25、33、53；见姊妹站深读。"),("难点","“从父与子而出”（filioque）是东西教会的分歧点；BC 采用西方表述。"),("应用","祷告时有意识地向父、藉着子、在圣灵里。")]),
      ("第 12–15 条：创造、护理、人与原罪","#81b29a",[("成因与处境","对机械宿命、偶然与自由意志的论争：一方面神掌管一切，一方面神不是罪的创造者。"),("说什么","创造与天使（"+bl(12)+"）；护理（"+bl(13)+"）；人被造与堕落（"+bl(14)+"）；原罪（"+bl(15)+"）。"),("关键句",Q("BC 13","没有神的旨意或许可，这世上什么也不会发生")+"；"+Q("BC 15","足以使全人类被定罪")+"。"),("联系","HC 6–11、26–28；Dort 3-4.1–4；创1–3；罗5:12–21。"),("难点","BC 14 用“生命的律”而不是“行为之约”的术语；弃绝一切“自由意志”教导，是 Dort 的前奏。"),("应用","受苦时从 BC 13 得安慰：“任何事临到我们皆非出于偶然”（原文意思）。")]),
      ("第 16–18 条：拣选、应许、道成肉身","#d4af37",[("成因与处境","BC 先说堕落（14–15），再说神的“拣选”（16）与应许（17）——次序表明：救恩的根在神自己。"),("说什么","神彰显恩慈与公义（"+bl(16)+"）；神寻找人，以应许安慰人（"+bl(17)+"）；神成就应许，差遣子取了真正的人性（"+bl(18)+"）。"),("关键句",Q("BC 16","神的恩慈体现在神不看人的行为")+"；"+Q("BC 17","他以赐下独生子这一应许安慰人")+"。"),("联系","Dort 1（拣选）；HC 19、35–36；创3:15；加4:4。"),("应用","把“拣选”读为安慰：救恩不是人的成就，而是神的恩典。")]),
      ("第 19 条：基督位格中的二性","#d4af37",[("成因与处境","基督论的边界：不分、不混；古代信经（尼西亚、亚他那修）的遗产。"),("说什么","神人二性合于一个位格；神性与人性各有其特性（"+bl(19)+"）。"),("关键句",Q("BC 19","天地间不存在两位神子，神子也不具有两个位格")),("联系","亚他那修信经29–37；HC 16–18、35–36、46–48；WCF 8.2。"),("难点","这一条是 PRCA 在三大信经之外加上迦克墩信经的理由（据搜索摘录）；本站不评论各教会做法，只指出 BC 19 与迦克墩精神一致。"),("应用","读福音书时，同时看见他“累了”（人）与“平静风浪”（神）。")]),
      ("第 20–21 条：神的公义与怜悯；基督的救赎","#d4af37",[("成因与处境","如何理解十字架？不是神的“不公”，而是神的公义与怜悯同时被彰显。"),("说什么","公义与怜悯（"+bl(20)+"）；基督是永远的大祭司，代替我们献上自己（"+bl(21)+"）。"),("关键句",Q("BC 20","他就在他儿子身上彰显了公义，同时也将他的良善与怜悯倾倒在我们这些有罪的、当受咒诅的人身上")),("联系","HC 11–18、37–44；Dort 2.1–4；来7–10；赛53。"),("应用","十字架让我们既不轻看罪，也不对恩典绝望。")]),
      ("第 22–26 条：信心称义、成圣、律法、代求","#e0a85f",[("成因与处境","改革宗对“如何得救”的回答：信心是圣灵所生，称义唯独靠基督，善行是果子。"),("说什么","真信心由圣灵在心中生发（"+bl(22)+"）；罪得赦免，称为义（"+bl(23)+"）；真信心必结善行（"+bl(24)+"）；礼仪律已成全，律法与先知的见证仍有用（"+bl(25)+"）；唯一的中保与代求者（"+bl(26)+"）。"),("关键句",Q("BC 22","圣灵在我们心中生发真信心")+"；"+Q("BC 26","没有其他途径可以让人来到神面前")+"。"),("联系","HC 21、23–24、60–64、86–91；Dort 2.8、3-4.14、5；罗3–5；加2–3。"),("应用","警惕“基督加上某物”的福音：BC 22 称那是“半个救主”。")]),
      ("第 27–32 条：教会","#e07a5f",[("成因与处境","在多个教派都自称“真教会”的16世纪，BC 提供辨别的标志；同时在逼迫中，教会需要明确的治理与纪律。"),("说什么","圣而公之教会（"+bl(27)+"）；加入教会的责任（"+bl(28)+"）；真假教会的标志——纯正福音、圣礼、纪律（"+bl(29)+"）；教会的治理：牧师、长老、执事（"+bl(30)+"）；圣职的产生（"+bl(31)+"）；规章与纪律（"+bl(32)+"）。"),("关键句",Q("BC 29","她宣讲纯正的福音；她按照基督当初设立圣礼的样式施行圣礼；她为纠正错误、刑罚罪恶而执行教会纪律")),("联系","HC 21、31；Dort 5.3；CCI 教会规章与《烛台宣言》3.3；URCNA 与 CanRC 对教会治理的陈述。"),("难点","“真教会的标志”不是说其他教会里没有信徒，而是说“辨别真教会”要看福音、圣礼与纪律。"),("应用","找教会时看“纯正的福音”，而不仅是气氛。")]),
      ("第 33–35 条：圣礼","#e07a5f",[("成因与处境","16世纪最激烈的争论之一：圣礼的数目、功效与基督的同在。"),("说什么","圣礼是印证（"+bl(33)+"）；洗礼：取代割礼，信徒的婴孩应受洗，弃绝重洗派（"+bl(34)+"）；圣餐：属灵的喂养，凭信心吃喝，基督在天上却通过信心与我们相交（"+bl(35)+"）。"),("关键句",Q("BC 33","圣礼是内在不可见之事的外在标记与印证")+"；"+Q("BC 35","我们不是用嘴吃喝，而是凭信心用心灵吃喝")),("联系","HC 65–85；Dort 1.17；WCF 27–29；创17；西2:11。"),("应用","参加圣礼是“信心的操练”，而不是“仪式的完成”。")]),
      ("第 36–37 条：政府与末日审判","#6bb8d6",[("成因与处境","逼迫的背景使政府与末日成为实际的问题：信徒怎样对待不义的政权？最终的盼望是什么？"),("说什么","官长的设立（"+bl(36)+"）：刑罚作恶、保护行善，也保护教会与福音的传播；信徒当顺服并代祷；谴责造反者。末日：基督有形有体地再来，审判活人死人，对蒙选者是“极大的喜乐和安慰”（"+bl(37)+"）。"),("关键句",Q("BC 36","我们应该为他们代祷")+"；"+Q("BC 37","因此，我们极其盼望那日的到来")),("联系","HC 19、52、57–58；Dort 5；罗13；启20–22。"),("难点","BC 36 的第一段与结尾曾有修订（见3.5）；教会与政府的关系在各国教会中有不同的理解。"),("应用","受逼迫的教会写“顺服官长”；今天读这条，也要读“在不违反圣经的一切事上”的限度。")])],open_first=True)
    b += L2("bcd-deep","3.6","逐组深读：成因、内容、联系、难点、应用",dv)
    # 3.7 特点表
    b += L2("bcd-feat","3.7","BC 的特点：与 HC、Dort 对照",
      table(["主题","BC 的位置","HC / Dort 的对应","BC 的特色"],[
        ["圣经","BC 2–7（六条）","HC 21–22 只在信心定义中提","最完整的“圣经论”，明确正典与次经"],
        ["三位一体","BC 8–11","HC 24–25、53","条文式的“教义陈述”"],
        ["拣选","BC 16","Dort 1 全项","简短，只谈恩慈与公义，细节留给 Dort"],
        ["教会","BC 27–32（六条）","HC 21、31","<b>三标志</b>与治理、纪律"],
        ["圣礼","BC 33–35","HC 25–31","对重洗派的明确回应"],
        ["政府","BC 36","HC 39（权威）","<b>唯一</b>专论官长的文件"],
        ["末日","BC 37","HC 19、22、52","以“盼望的告白”结束"]],"cmp")
      + key("<b>BC 独有三件：</b>圣经论完整（2–7）、教会论完整（27–32）、政府论（36）。这三件是它作为“告白书”面向社会与教会的两个“窗口”。"))
    # 3.8 误解
    b += L2("bcd-myth","3.8","常见误解",
      myths([("BC 只是加尔文《法国信条》的修改版","CCI：BC 得益于法国信条，但“并不是加尔文所写信条的修正版，而是有其自身特点的独立信条”。"),
             ("BC 的目的是辩论","CCI：写作是为了抗议逼迫、向官长表明信徒是守法公民，并向教会宣告真信仰。"),
             ("BC 36 要求教会控制国家","第36条说官长也保护教会与福音，同时信徒不违反圣经地顺服；对造反者有明确谴责；教会与官长的具体关系，历史上有多种理解（见 3.5 的“难点”）。"),
             ("BC 只有教义，没有安慰","第13条（护理）与第37条（末日）都在说“安慰”；CCI 所载 Clarence Stam 的 LD52 讲道也指出（转述），三份联合信条都以“真信徒能持守信仰”的宣告作结。")]))
    # 3.9 人物
    b += L2("bcd-ppl","3.9","人物",
      people([("德布利（Guido de Brès）","约1522–1567","荷兰改革宗教会的牧师，BC 的主要作者；1567年为主殉道（CCI）。","#d4af37"),
              ("加尔文（John Calvin）","1509–1564","法国信条（1559）的主笔（CCI）；对 BC 有影响，但 BC 是独立文件。","#5aa9e6"),
              ("腓利二世（Philip II）","西班牙与尼德兰之王","BC 的抄本与请愿书的收件人（CCI）。","#e07a5f"),
              ("尼德兰各总会","1568–1618","韦瑟尔、埃姆登、多特、米德尔堡、海牙：逐步审议、采纳与修订（CCI 教会规章导言与 BC 导言）。","#81b29a")]))
    # 3.10 使用
    b += L2("bcd-use","3.10","在教会生活中的使用：签署、告白与教导",
      '<p>CCI 的《赞美手册》把 BC 放在日常教会程序中，而不是只放在教义课里：</p>'
      + table(["CCI 材料","要点","链接"],[
          ["签署书（供地方教会使用）","牧师、长老、执事共同签署，真诚宣告相信 BC、HC、Dort 所含全部教义“均完全符合圣经”："+M("forms1","我们真心相信《比利时信条》、《海德堡要理问答》和《多特信经》中所包含的全部教义均完全符合圣经"),mu("forms1")],
          ["签署书（供地方会议使用）","同上，由隶属某地方会议的牧师共同签署",mu("forms2")],
          ["公开信仰告白仪文","第一问："+M("lf3","你是否完全相信归纳在信条中，并在本教会宣讲的圣经教义"),mu("lf3")],
          ["《烛台宣言》3.3","第三十二条反对“教条使教会僵化”的说法："+M("cs33","三十二、基于本文表达了我们的坚信，我们拒绝有教导说，这类教条或教义是对教会生命发展的阻碍"),mu("cs33")],
          ["《真理的火焰》第1章","作者指出 HC 与 BC 是“三项联合信条”的一部分，记载耶稣基督看顾教会的事迹（转述）",A(CCI+"/books/flame-of-truth/1","flame-of-truth/1")]],"cmp")
      + app("如果你要在教会里首次系统读 BC：每周一至两条，按本页的七群分段；读完后，用 CCI 公开信仰告白的第一问自问：我是否愿意在神与教会面前，承认这些教义？")
      + note("签署书条文的“承诺”部分（教导、捍卫、不私下传讲异议）见第五部分对“签署”的讨论。"))
    import c_viz
    b += c_viz.viz_bc()
    import c_refx
    b += c_refx.l2("bc")
    return L1("bc","三","比利时信条深读","scroll","德布利、1561 与逼迫：37 条的结构、成因与应用；逐字原文见第八部分。", b)
